record.field:
action = False
evaluation_model = env['x_hr.employee_performance_evaluation'].sudo()


def toast(title, message, kind='warning', sticky=False):
    return {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': title,
            'message': message,
            'type': kind,
            'sticky': sticky,
        }
    }


employee = records[:1].sudo() if records else False
if not employee:
    active_id = env.context.get('active_id') or env.context.get('default_x_employee_id')
    employee = env['hr.employee'].sudo().browse(active_id) if active_id else False

if not employee or not employee.exists():
    action = toast('New Performance Evaluation', 'Open this action from an employee record so the evaluation can be linked and seeded correctly.', 'warning', True)
else:
    evaluation = evaluation_model.create({
        'x_employee_id': employee.id,
        'x_state': 'draft',
        'x_max_score': 60,
        'x_grade': 'not_scored',
        'x_star_rating': '0',
        'x_responsible_user_id': env.user.id,
        'x_direct_manager_employee_id': employee.parent_id.id if employee.parent_id else False,
        'x_direct_manager_user_id': employee.parent_id.user_id.id if employee.parent_id and employee.parent_id.user_id else False,
    })

    # The 21C create automation seeds the 12 lines synchronously.
    evaluation = evaluation_model.browse(evaluation.id)

    view = env.ref('hr_employment_custom.view_employee_performance_evaluation_form', raise_if_not_found=False)

    action = {
        'type': 'ir.actions.act_window',
        'name': evaluation.x_name or 'New Performance Evaluation',
        'res_model': 'x_hr.employee_performance_evaluation',
        'res_id': evaluation.id,
        'view_mode': 'form',
        'target': 'new',
        'context': {
            'default_x_employee_id': employee.id,
        },
    }
    if view:
        action['views'] = [(view.id, 'form')]
